from pathlib import Path
TODAY='2026-06-18'
def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def render(title,path,pos,concepts,asks,triage,combined,analysis):
 c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts))
 a='\n'.join(f"- {x}" for x in asks)
 t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage)
 cb='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in combined)
 an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
 write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：标题里的概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、品类、咨询口径与即时零售场景\n\n| 品类/服务 | 对应场景 | 药师提醒点 | 平台/药店承接点 |\n|---|---|---|---|\n{cb}\n\n## 五、对平台、药店、药企的业务分析\n\n{an}\n''')

render('结膜炎眼干眼部不适基础概念','08-疾病与医学基础/补充资料/结膜炎眼干眼部不适基础概念.md',
'本文回答：结膜炎、眼干、眼部不适分别是什么，为什么用户会把“眼红、眼痒、干涩、异物感”混在一起搜索，以及药店和平台应如何识别眼科红旗信号。核心判断是：眼部轻症适合承接人工泪液、过敏护理和药师咨询，但视力下降、眼痛、畏光、外伤、化学品接触和隐形眼镜相关风险必须优先就医。',
[('结膜炎：眼红和分泌物提示结膜炎症，但病因不同','结膜炎是结膜发生炎症后的表现，常见症状包括眼红、异物感、流泪、分泌物增多、眼痒或轻度烧灼感。它可能由病毒、细菌、过敏或刺激物引起。病毒性、细菌性和过敏性处理思路不同，不能只凭“眼红”自动推荐抗菌眼药。'),('眼干：核心是泪膜不稳定和眼表不适','眼干常表现为干涩、异物感、疲劳、烧灼感、畏风、看屏幕后加重或反复眨眼。它可能与长期用眼、环境干燥、隐形眼镜、部分药物、睑板腺功能异常或年龄相关。人工泪液可用于轻症支持，但持续眼痛和视力变化不是普通眼干。'),('眼部不适：是用户口语，需要拆成痛、痒、干、红、分泌物和视力变化','用户说“眼睛不舒服”可能是干眼、过敏、感染、角膜问题、外伤、异物或青光眼等。药店咨询必须追问具体感受。眼痛、畏光、视力下降和外伤是比“眼红”更重要的风险信号。'),('隐形眼镜相关不适：需要单独提高警惕','佩戴隐形眼镜后出现红痛、畏光、分泌物或视力下降，不能当作普通眼干处理。角膜感染风险更高，应优先建议眼科评估。')],
['单眼还是双眼，是否视力下降、眼痛、畏光或明显异物感。','是否有分泌物，分泌物是清水样、黏稠还是脓性；是否眼痒和季节性过敏。','是否佩戴隐形眼镜，是否有外伤、异物、化学品接触或近期眼科手术。','症状持续多久，是否反复，是否伴头痛、恶心或眼压相关不适。','已经使用哪些眼药水，是否含抗菌、激素、防腐剂或多种眼药叠加。'],
[('轻症咨询','轻度干涩、屏幕疲劳、轻度眼痒，无视力变化和眼痛','人工泪液、眼部护理、过敏诱因提醒','不推荐处方眼药或长期自行用药'),('药师重点判断','眼红分泌物、反复发作、隐形眼镜佩戴者轻度不适','追问分泌物、佩戴史和风险，必要时建议眼科','不滥用抗菌/激素眼药'),('优先就医','视力下降、眼痛、畏光、外伤、化学品、隐形眼镜相关红痛','提示眼科就医','不靠自购眼药处理')],
[('人工泪液','屏幕用眼、轻度眼干、家庭常备','注意防腐剂、使用频次和持续症状','按干涩场景展示，不替代眼科评估'),('抗过敏眼部用品','眼痒、流泪、季节性过敏','严重红痛或视力变化需就医','过敏季备货和药师咨询'),('眼部清洁护理','轻度刺激、睑缘清洁、护理需求','不替代感染或角膜问题评估','护理用品与教育内容绑定'),('处方眼药','医生诊断后使用','不自行购买抗菌/激素类眼药','处方核验和风险提示'),('眼科就医提醒','红旗信号或隐形眼镜风险','视力和眼痛优先级高于配送','平台拦截高风险眼部搜索')],
[('平台','眼部入口必须区分干、痒、红、痛、视力变化；眼痛和视力下降应触发就医提醒。'),('药店','药师应重点询问隐形眼镜、外伤、分泌物和既往用药，不应把所有眼红都导向抗菌眼药。'),('药企','眼科产品教育应讲清适用场景、防腐剂、使用频次和就医信号。')])

render('过敏鼻炎皮炎湿疹基础概念','08-疾病与医学基础/补充资料/过敏鼻炎皮炎湿疹基础概念.md',
'本文回答：过敏性鼻炎、皮炎、湿疹分别是什么，为什么它们都属于高频药店咨询和即时零售场景。核心判断是：过敏类需求适合承接抗过敏、鼻喷、保湿修复和药师咨询，但必须先区分鼻部过敏、皮肤炎症和严重过敏反应。',
[('过敏性鼻炎：鼻黏膜对过敏原的反应，不是普通感冒','过敏性鼻炎常表现为阵发性打喷嚏、清水样鼻涕、鼻痒、鼻塞，可伴眼痒流泪。它常与花粉、尘螨、宠物皮屑、霉菌或季节变化相关。与感冒相比，过敏性鼻炎通常更反复、鼻痒更明显、全身感染症状较轻。'),('皮炎：皮肤炎症的宽泛说法，需要看诱因和形态','皮炎可以由接触刺激、过敏、感染、药物或皮肤屏障受损引起，表现为红斑、丘疹、瘙痒、干燥、脱屑、渗出或疼痛。药店不能看到“皮肤痒”就只推荐止痒药，要先看范围、形态和是否感染。'),('湿疹：常见慢性反复皮肤炎症，护理和避免诱因很重要','湿疹常反复发作，皮肤干燥、瘙痒、红斑、脱屑或渗出可交替出现。长期管理不只是外用药，还包括保湿修复、减少刺激、识别诱因和避免抓挠。'),('严重过敏反应：和普通过敏完全不是一个等级','面唇舌肿胀、喉咙发紧、呼吸困难、全身风团、头晕或血压下降可能提示严重过敏反应。平台和药店必须把这类信号从普通鼻炎/皮炎场景中拦截出来。')],
['主要是鼻部症状、皮肤症状，还是全身过敏反应。','是否季节性、接触宠物/花粉/新护肤品/食物/药物后出现。','皮疹范围、是否渗出、疼痛、感染、眼周或面部肿胀。','是否有哮喘、严重过敏史、儿童或孕妇等特殊情况。','已经使用哪些口服抗过敏药、鼻喷、外用激素或抗生素。'],
[('轻症自我管理','轻度鼻痒喷嚏、局部干痒皮疹、无全身反应','抗过敏/保湿/护理咨询','不长期自行用强效外用药'),('药师重点判断','反复发作、儿童、面部皮疹、渗出或用药不清','询问诱因和用药史，必要时建议就医','不把感染当过敏'),('优先就医','呼吸困难、面唇舌肿胀、全身风团、严重渗出感染','提示就医','不只推荐抗过敏药')],
[('口服抗过敏药','鼻痒喷嚏、皮肤瘙痒、夜间急用','注意嗜睡、驾驶、儿童孕妇和老人','按鼻炎/皮肤场景分流'),('鼻喷/鼻腔护理','鼻塞鼻痒、季节性鼻炎','正确使用方式和疗程意识','花粉季提前备货和教育'),('保湿修复用品','湿疹、干燥、屏障受损','长期护理，避免刺激','家庭常备和复购'),('外用药','局部皮炎湿疹','部位、强度、疗程和感染信号需谨慎','药师咨询后展示'),('严重过敏拦截','呼吸或面部肿胀风险','就医优先','不以商品推荐替代急救')],
[('平台','过敏入口要把鼻炎、皮炎、湿疹和严重过敏反应分开，不应一个抗过敏药列表解决所有问题。'),('药店','药师应识别感染性皮损和严重过敏，指导保湿修复和外用药边界。'),('药企','过敏类产品教育应围绕诱因、症状类型、适用人群和长期护理。')])

render('肥胖与GLP1基础概念','08-疾病与医学基础/补充资料/肥胖与GLP1基础概念.md',
'本文回答：肥胖、体重管理和GLP-1相关药物分别是什么，为什么不能把GLP-1写成普通减肥商品。核心判断是：肥胖是慢性代谢风险管理问题，GLP-1相关药物属于处方和长期管理场景，平台可以承接复购、冷链和药师教育，但不能把体重焦虑转化为自行购药。',
[('肥胖：不是单纯体重数字，而是代谢风险状态','肥胖通常需要结合BMI、腰围、体脂分布和合并症风险理解。它与2型糖尿病、高血压、高脂血症、脂肪肝、睡眠呼吸暂停和心血管风险相关。用户想减重，不能只问“多少斤”，还要看代谢风险和既往减重方式。'),('GLP-1相关药物：处方药和长期管理工具','GLP-1受体激动剂等药物可用于特定糖尿病或体重管理适应症，但需要医生评估、处方、剂量递增、不良反应监测和复诊。它不是普通瘦身产品，也不适合无处方自行购买。'),('体重管理服务：生活方式仍是底层基础','饮食结构、运动、睡眠、行为管理、合并症控制和长期随访仍是体重管理基础。药物可能是治疗方案的一部分，但不能替代生活方式和医生评估。'),('平台风险：热度会放大不合规购药和滥用','社交媒体热度会让用户用药名直接搜索。平台若只展示商品，会把处方药风险变成消费品转化。合规拦截、处方核验和不良反应教育是核心。')],
['身高体重、BMI、腰围、近期体重变化和减重目标。','是否有糖尿病、高血压、脂肪肝、睡眠呼吸暂停或心血管风险。','是否已有医生处方，药物名称、剂量、起始时间和递增阶段。','是否有恶心、呕吐、腹痛、脱水、低血糖等不适。','是否孕期、哺乳期、胰腺炎史、胆囊疾病、肾功能异常或非正规渠道购药。'],
[('稳定处方复购','医生评估后长期管理，处方清楚','处方核验、冷链/库存、用药教育','不引导无处方购买'),('药师重点判断','胃肠反应、剂量不清、合并降糖药或漏用','提醒联系医生和监测风险','不自行调剂量'),('优先就医','严重腹痛、持续呕吐脱水、疑似胰腺炎、严重低血糖','提示就医','不靠续购处理')],
[('GLP-1处方药','处方复购、冷链配送、剂量阶段咨询','核对适应症、处方、剂量和不良反应','处方核验、冷链履约、药师提示'),('体重管理用品','体重秤、腰围、饮食运动记录','辅助管理，不替代治疗','记录工具和长期内容服务'),('药师咨询','胃肠反应、合并降糖药、漏用','提示医生联系和复诊','在线药师而非自动推荐'),('生活方式服务','饮食运动睡眠管理','长期基础，不能被药物替代','内容教育与复购提醒'),('合规拦截','无处方搜索GLP-1药名','处方药不能普通商品化','限制转化、提示就医评估')],
[('平台','GLP-1入口必须以处方核验、冷链和风险教育优先，不能做普通减肥商品转化。'),('药店','药师应关注剂量阶段、胃肠反应、低血糖风险、冷链和复诊。'),('药企','教育重点应是规范适应症、长期管理和不良反应识别，而不是体重焦虑营销。')])

